window.QA_TUTOR_NOTES = {
"sql-select": {"model":"Запрос покажет только названия всех товаров. После SELECT указан столбец name. Цена и остаток не выбраны, поэтому в результате их не будет. Условия WHERE нет, значит товары не отбираются по наличию.","observations":["В выбранном ответе верно, что речь идёт обо всех товарах.","Ты выбрал и нужный столбец, и правильный набор товаров.","В выбранном ответе верно указан столбец name — названия товаров."],"corrections":["Но все товары и все столбцы — не одно и то же. Запрос берёт из каждой строки только название. Чтобы вывести ещё цену и остаток, их нужно перечислить после SELECT.",null,"Но запроса на проверку наличия здесь нет. Товар с остатком 0 тоже будет показан. Для отбора по наличию понадобилось бы WHERE stock > 0."],"remember":"SELECT выбирает столбцы. WHERE отбирает строки. Это два разных действия.","checkpoint":{"prompt":"Теперь после SELECT написано price: SELECT price FROM products; Что будет показано?","choices":["Только цены всех товаров.","Названия и цены всех товаров."],"answer":0,"explain":"Будут показаны только цены: выбран один столбец price. Чтобы добавить названия, нужно SELECT name, price.","sql":"SELECT price FROM products;","rows":[["Телефон A",1800,2],["Телефон B",2200,0]],"expected":[[1800],[2200]]}},
"sql-greater": {"model":"Нужно выбрать price > 2000. По-русски это читается: «цена больше 2000». Телефон за 2200 ₪ подходит, за 1500 ₪ — нет. Телефон ровно за 2000 ₪ также не подходит, потому что в задании сказано «строго дороже».","observations":["Ты выбрал нужное поле price и нужную сумму 2000.","Ты выбрал нужное поле, направление сравнения и правильно исключил цену ровно 2000.","Ты выбрал поле цены и направление «больше»."],"corrections":["Но знак < означает «меньше». Он нашёл бы телефоны дешевле 2000 ₪. Здесь требуется противоположный знак: >.",null,"Лишний знак равенства меняет результат. Условие >= включит телефон ровно за 2000 ₪, хотя по заданию его включать нельзя."],"remember":"Дороже — >. Дешевле — <. Ровно указанная сумма включается только при соответствующем знаке равенства.","checkpoint":{"prompt":"Цена телефона — ровно 2000 ₪. Выберет ли его условие price >= 2000?","choices":["Нет, оно выбирает только более дорогие телефоны.","Да, здесь разрешена и цена ровно 2000."],"answer":1,"explain":"Да. Знак >= читается «больше или равно». Поэтому телефон за 2000 ₪ тоже подходит.","sql":"SELECT name FROM products WHERE price >= 2000;","rows":[["Телефон A",2000,1]],"expected":[["Телефон A"]]}},
"sql-boundary": {"model":"Нет, телефон за 2500 ₪ не будет показан. Запрос ищет товары дешевле 2500 ₪, а этот телефон стоит ровно столько. Запрос выполнится нормально, просто подходящих товаров в этой учебной таблице нет.","observations":[null,"Ты правильно отличил «дешевле 2500» от «2500 или дешевле».","В ответе замечена важная ситуация: цена совпадает с указанной границей."],"corrections":["Знак < означает «меньше», без равенства. Цена 2499 ₪ подошла бы, а 2500 ₪ — уже нет. Чтобы включить 2500 ₪, понадобилось бы <=.",null,"Но совпадение с границей не ломает SQL-запрос. Товар просто не подходит под условие. Отсутствие товаров в результате — не ошибка выполнения."],"remember":"Нет подходящих строк и ошибка запроса — разные ситуации.","checkpoint":{"prompt":"А телефон за 2499 ₪ попадёт в результат WHERE price < 2500?","choices":["Да, 2499 меньше 2500.","Нет, подходят только товары ровно за 2500."],"answer":0,"explain":"Да, попадёт: 2499 ₪ дешевле 2500 ₪. Именно такую цену и допускает знак <.","sql":"SELECT name FROM products WHERE price < 2500;","rows":[["Телефон A",2499,1]],"expected":[["Телефон A"]]}},
"sql-and": {"model":"Нет, этот товар не попадёт в результат. Цена подходит: 2200 ₪ меньше 2500 ₪. Но на складе 0 штук — товар закончился. Запрос требует и подходящую цену, и наличие, поэтому одной цены недостаточно.","observations":["В выбранном варианте правильно указано сравнение цены: 2200 ₪ меньше 2500 ₪.","Ты выбрал правильную причину: товар отсутствует на складе.","Вывод «не попадёт» совпадает с результатом, но причина указана другая."],"corrections":["Осталось учесть второе условие — наличие. stock > 0 означает, что на складе должна быть хотя бы одна единица товара. Сейчас их 0, поэтому запрос этот товар не покажет.",null,"Запрос не требует цену больше 2500. Знак < означает «меньше», и цена 2200 подходит. Товар исключается из-за отсутствия на складе."],"remember":"AND — «И». Представь просьбу: «Покажи недорогие телефоны, которые можно купить сейчас». Дешёвый, но закончившийся телефон не подойдёт.","checkpoint":{"prompt":"Теперь у того же товара цена 2200 ₪, а на складе 3 штуки. Покажет ли его тот же запрос?","choices":["Нет, наличие не влияет на этот запрос.","Да: и цена подходит, и товар есть на складе."],"answer":1,"explain":"Да. Цена 2200 ₪ меньше 2500 ₪, а 3 штуки — это больше нуля. Теперь выполнены оба требования.","sql":"SELECT name FROM products WHERE price < 2500 AND stock > 0;","rows":[["Учебный телефон",2200,3]],"expected":[["Учебный телефон"]]}},
"sql-fields": {"model":"Правильный запрос: SELECT name, price FROM products;. Он покажет названия и цены всех товаров. Два столбца перечислены через запятую. Остаток stock не указан, поэтому в результате его не будет.","observations":["В твоём варианте названы нужные поля name и price.","Твой вариант действительно получает данные из нужной таблицы products.","Ты выбрал ровно два нужных столбца и разделил их запятой."],"corrections":["Но между столбцами нужна запятая, не AND. AND соединяет условия. В SQLite вариант с AND может выполниться, но вернёт одно вычисленное выражение вместо двух нужных столбцов.","Звёздочка выбирает все столбцы таблицы, в том числе stock. По заданию нужны только name и price, поэтому их надо перечислить явно.",null],"remember":"Перечисляем столбцы — ставим запятую. Соединяем условия — используем AND.","checkpoint":{"prompt":"Нужны только название и остаток. Какой запрос подходит?","choices":["SELECT name AND stock FROM products;","SELECT * FROM products;","SELECT name, stock FROM products;"],"answer":2,"explain":"Нужен SELECT name, stock FROM products;. В результате два выбранных столбца, разделённых запятой.","sql":"SELECT name, stock FROM products;","rows":[["Телефон A",1800,2],["Телефон B",2200,0]],"expected":[["Телефон A",2],["Телефон B",0]]}},
"sql-order": {"model":"Нужно ORDER BY price DESC. Поле price задаёт сортировку по цене, а DESC — от большего значения к меньшему. Поэтому сначала будут 3000 ₪, затем 2500 ₪, 2200 ₪ и 1500 ₪.","observations":["Ты выбрал сортировку по правильному полю price.","Ты выбрал сортировку по цене в нужном направлении.","Ты выбрал направление DESC — по убыванию."],"corrections":["Но ASC расположит товары от дешёвых к дорогим. В этом задании нужно наоборот, поэтому требуется DESC.",null,"Но name — это название, а не цена. Сортировка названий не выполняет просьбу «от дорогих к дешёвым». Нужно заменить name на price."],"remember":"Сначала спроси «по какому полю?», затем «в каком направлении?». price DESC — от дорогих к дешёвым, price ASC — наоборот.","checkpoint":{"prompt":"Есть цены 1800, 3000 и 900 ₪. Каким будет порядок при ORDER BY price ASC?","choices":["900 → 1800 → 3000.","3000 → 1800 → 900."],"answer":0,"explain":"ASC — по возрастанию: 900, затем 1800, затем 3000 ₪. Это порядок от дешёвых к дорогим.","sql":"SELECT price FROM products ORDER BY price ASC;","rows":[["Телефон A",1800,1],["Телефон B",3000,1],["Телефон C",900,1]],"expected":[[900],[1800],[3000]]}}
};
